✅️ qMap_total_fiber_one_level_eq 𝔽q β i i.isLt
  y : ∀ (k : Fin 2),
  have basis_x := sDomain_basis 𝔽q β h_ℓ_add_R_rate ⟨↑i, ⋯⟩ ⋯;
  have x := qMap_total_fiber 𝔽q β ⟨↑i, ⋯⟩ 1 ⋯ y k;
  have y_lifted := sDomain.lift 𝔽q β h_ℓ_add_R_rate ⟨↑i, ⋯⟩ ⟨↑i + 1, ⋯⟩ ⋯ ⋯ y;
  have free_coeff_term := Fin2ToF2 𝔽q k • basis_x ⟨0, ⋯⟩;
  x = free_coeff_term + y_lifted

